// FanGraphs player-id resolution for the projections-v2 pool "FG" link.
//
// a collaborator 2026-06-22: v1 of the FG link was a Google search (we stored no
// FanGraphs IDs). This resolves a real FanGraphs id + url slug from a static
// crosswalk (web/src/data/fangraphs-ids.json, generated by
// scripts/build_fangraphs_crosswalk.py from the SFBB PLAYERIDMAP) so the link
// deep-links straight to /players/<slug>/<id>/splits.
//
// Imported server-side only (the API route), so the 258 KB crosswalk never
// reaches the client bundle. The route attaches fg_id/fg_slug per player and
// the page renders the deep-link, falling back to the search link when null.
import crosswalk from "@/data/fangraphs-ids.json";
import { canonDkTeam } from "@/lib/fd-slate";

interface FgEntry {
  team: string; // raw SFBB team — canonicalized at compare time, not at build
  id: string;
  slug: string;
}
const MAP = crosswalk as Record<string, FgEntry[]>;

const SUFFIXES = new Set(["jr", "sr", "ii", "iii", "iv", "v"]);

/** MUST match norm_name() in scripts/build_fangraphs_crosswalk.py exactly. */
export function normName(s: string): string {
  const stripped = (s || "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
  const cleaned = stripped.replace(/[^a-z0-9]+/g, " ").trim();
  return cleaned
    .split(/\s+/)
    .filter((t) => t && !SUFFIXES.has(t))
    .join(" ");
}

/**
 * Resolve a pool player to a FanGraphs id + slug, or null when unknown or
 * ambiguous. A unique name match wins outright; a same-name collision (two
 * Max Muncys) is disambiguated by canonical team and falls back to null —
 * never a wrong guess — when team can't pick exactly one.
 */
export function resolveFangraphs(
  name: string,
  team: string | null | undefined,
): { id: string; slug: string } | null {
  const entries = MAP[normName(name)];
  if (!entries || entries.length === 0) return null;
  if (entries.length === 1) return { id: entries[0].id, slug: entries[0].slug };
  const tk = canonDkTeam(team || "");
  if (!tk) return null;
  const hits = entries.filter((e) => canonDkTeam(e.team) === tk);
  return hits.length === 1 ? { id: hits[0].id, slug: hits[0].slug } : null;
}

/** Full splits-tab URL for a resolved player; pitchers get ?position=P. */
export function fangraphsSplitsUrl(
  fg: { id: string; slug: string },
  isPitcher: boolean,
): string {
  const base = `https://www.fangraphs.com/players/${fg.slug}/${fg.id}/splits`;
  return isPitcher ? `${base}?position=P` : base;
}
